// Lunar Dynamics Core: freestanding C++17, double precision. Normalized units.
struct V{double x,y; V operator+(V b)const{return{x+b.x,y+b.y};} V operator-(V b)const{return{x-b.x,y-b.y};} V operator*(double k)const{return{x*k,y*k};}};
static double root(double x){return __builtin_sqrt(x);} static double norm(V a){return root(a.x*a.x+a.y*a.y);} static double max(double a,double b){return a>b?a:b;} static double min(double a,double b){return a<b?a:b;} static V unit(V a){return a*(1/max(norm(a),1e-9));}
constexpr int B=5,N=48,F=12; struct Body{V p,v;double m,r,water;}; static Body b[B]; static V p[N],v[N],old[N],fish[F],fv[F]; static double data[256],length,tension,clock_,wear;static int active,wet,attached,caught,broken;static unsigned seed_; static double random(){seed_=1664525u*seed_+1013904223u;return (seed_>>8)/16777216.;}
static V grav(V x,int skip=-1){V a{};for(int j=0;j<B;j++)if(j!=skip){V d=b[j].p-x;double r=max(norm(d),b[j].r*.6);a=a+d*(b[j].m/(r*r*r));}return a;}
static V anchor(){return b[1].p+V{b[1].r+.8,0};}
extern "C" double* snapshot(){return data;}
extern "C" void reset(unsigned seed){seed_=seed;clock_=0;active=wet=caught=broken=0;attached=-1;length=1;tension=wear=0; b[0]={{0,-95},{0,0},2200,15,0};b[1]={{-100,-10},{-1.9,-3.2},12,10,0};b[2]={{-22,38},{-3.9,.3},340,19,0};b[3]={{63,-12},{-2.8,2.2},125,26,1};b[4]={{105,85},{-2.1,1.1},85,21,1.5};if(seed!=1){for(int j=2;j<B;j++){b[j].p.x+=(random()-.5)*24;b[j].p.y+=(random()-.5)*24;}} for(int i=0;i<N;i++){p[i]=anchor();v[i]=b[1].v;}for(int i=0;i<F;i++){int j=3+i/6;V d=unit({random()-.5,random()-.5});fish[i]=b[j].p+d*(b[j].r*(.55+.4*random()));fv[i]=b[j].v;}}
extern "C" void cast(double dx,double dy,double draw,int rod){if(active)return;V dir=unit({dx,dy});if(dir.x<-.15)dir=unit({-.15,dir.y});double k=rod?4800:2700;double speed=root(k*draw*draw/.8);length=1;active=1;wet=broken=caught=0;attached=-1;tension=wear=0;for(int i=0;i<N;i++){p[i]=anchor()+dir*(double(i)/(N-1));v[i]=b[1].v+dir*(speed*i/(N-1));}}
static void body_step(double dt){V a[B];for(int j=0;j<B;j++)a[j]=grav(b[j].p,j);for(int j=0;j<B;j++){b[j].v=b[j].v+a[j]*(dt*.5);b[j].p=b[j].p+b[j].v*dt;}for(int j=0;j<B;j++)b[j].v=b[j].v+grav(b[j].p,j)*(dt*.5);}
static void sub(double dt,int reel,double drag){clock_+=dt;body_step(dt);for(int i=0;i<F;i++){int j=3+i/6;V d=fish[i]-b[j].p;double r=norm(d);V u=unit(d),t={-u.y,u.x};V goal=b[j].v+t*(2+i%3*.5)+u*((b[j].r*.76-r)*.8);fv[i]=fv[i]+(goal-fv[i])*(dt*2);fish[i]=fish[i]+fv[i]*dt;} if(!active)return;
 p[0]=anchor();v[0]=b[1].v;wet=0;double path=0;for(int i=1;i<N;i++)path+=norm(p[i]-p[i-1]);if(reel)length=max(.8,length-(8+12*drag)*dt);else length=min(420,max(length,path+2*dt)+max(0.,norm(v[N-1]-b[1].v)*.8)*dt);
 for(int i=1;i<N;i++){old[i]=p[i];V a=grav(p[i]);for(int j=3;j<B;j++){double r=norm(p[i]-b[j].p);if(r<b[j].r){V rel=v[i]-b[j].v;double density=b[j].water;a=a*.28-rel*(min(24.,norm(rel)*.12+1.1)*density);if(i==N-1)wet=j;}}if(i==N-1&&attached>=0)a=a+(fish[attached]-p[i])*18+(fv[attached]-v[i])*2;v[i]=v[i]+a*dt;p[i]=p[i]+v[i]*dt;}
 double rest=length/(N-1),peak=0;double lambda[N]={};for(int it=0;it<14;it++){p[0]=anchor();for(int z=1;z<N;z++){int i=it%2?N-z:z;V d=p[i]-p[i-1];double r=norm(d),C=r-rest;double w=i==1?0:1,wh=i==N-1?.22:1,alpha=.000012/(dt*dt);double dl=max(-lambda[i],(C-alpha*lambda[i])/(w+wh+alpha));lambda[i]+=dl;V corr=unit(d)*dl;p[i]=p[i]-corr*wh;p[i-1]=p[i-1]+corr*w;}for(int i=1;i<N;i++)for(int j=0;j<B;j++){V d=p[i]-b[j].p;double rr=b[j].r*(b[j].water?.47:1)+.12;if(norm(d)<rr){p[i]=b[j].p+unit(d)*rr;if(i==N-1&&!b[j].water)wear+=dt*.012;}}}for(int i=1;i<N;i++){v[i]=(p[i]-old[i])*(1/dt);peak=max(peak,lambda[i]/(dt*dt));}tension=tension*.92+peak*.08;wear+=max(0.,tension-1300)*dt*.00002;if(wear>1){active=0;broken=1;attached=-1;return;}
 if(attached<0&&wet&&norm(v[N-1]-b[wet].v)<18){for(int i=0;i<F;i++)if(3+i/6==wet&&norm(fish[i]-p[N-1])<5){attached=i;break;}}if(attached>=0){fish[attached]=p[N-1]+unit(fv[attached]-v[N-1])*1.4;}
 if(reel&&norm(p[N-1]-anchor())<4&&length<15){caught=attached>=0?attached+1:0;active=0;attached=-1;}}
extern "C" void step(double dt,int reel,double drag){int n=1;for(int j=0;j<B;j++)if(active&&norm(p[N-1]-b[j].p)<b[j].r*2)n=3;for(int i=0;i<n;i++)sub(dt/n,reel,drag);data[0]=clock_;data[1]=active;data[2]=wet;data[3]=attached;data[4]=caught;data[5]=broken;data[6]=length;data[7]=tension;data[8]=wear;for(int j=0;j<B;j++){data[10+j*4]=b[j].p.x;data[11+j*4]=b[j].p.y;data[12+j*4]=b[j].r;data[13+j*4]=b[j].water;}for(int i=0;i<N;i++){data[32+2*i]=p[i].x;data[33+2*i]=p[i].y;}for(int i=0;i<F;i++){data[128+2*i]=fish[i].x;data[129+2*i]=fish[i].y;}}
extern "C" void* memset(void* p,int c,__SIZE_TYPE__ n){volatile unsigned char* q=(volatile unsigned char*)p;for(__SIZE_TYPE__ i=0;i<n;i++)q[i]=(unsigned char)c;return p;}
